/**
 * Tests for useLocationSearch hook.
 */

import { renderHook } from '@testing-library/react';
import { useLocationSearch } from './useLocationSearch';
import { normalizeNavGraph } from '../domain/navGraph';
import { NavBuilding, NavFloor, NavGraph } from '../../src/shared/types';

function createTestNavGraph(): NavGraph {
  const libF1Nodes = [
    { id: 'lib-f1-entrance', x: 0.5, y: 0.9, floorId: 1, type: 'entrance' as const, searchable: true, label: 'Main Entrance', description: 'Library main entrance' },
    { id: 'lib-f1-reception', x: 0.5, y: 0.8, floorId: 1, type: 'room' as const, searchable: true, label: 'Reception', roomNumber: '101', description: 'Front desk' },
    { id: 'lib-f1-study-a', x: 0.3, y: 0.6, floorId: 1, type: 'room' as const, searchable: true, label: 'Study Room A', roomNumber: '102' },
    { id: 'lib-f1-stairs', x: 0.9, y: 0.5, floorId: 1, type: 'stairs' as const, searchable: false, label: 'Stairs', connectsToNodeAboveId: 'lib-f2-stairs', connectsToFloorAboveId: 2 },
    { id: 'lib-f1-elevator', x: 0.1, y: 0.5, floorId: 1, type: 'elevator' as const, searchable: true, label: 'Elevator' },
  ];
  const libF2Nodes = [
    { id: 'lib-f2-stairs', x: 0.9, y: 0.5, floorId: 2, type: 'stairs' as const, searchable: false, label: 'Stairs', connectsToNodeBelowId: 'lib-f1-stairs', connectsToFloorBelowId: 1 },
    { id: 'lib-f2-cafeteria', x: 0.5, y: 0.7, floorId: 2, type: 'landmark' as const, searchable: true, label: 'Cafeteria', roomNumber: '201' },
  ];
  const sciF1Nodes = [
    { id: 'sci-f1-entrance', x: 0.5, y: 0.9, floorId: 3, type: 'entrance' as const, searchable: true, label: 'Science Entrance', description: 'Science building main entrance' },
    { id: 'sci-f1-lab-101', x: 0.3, y: 0.5, floorId: 3, type: 'room' as const, searchable: true, label: 'Chemistry Lab', roomNumber: '101', description: 'Teaching chemistry lab' },
    { id: 'sci-f1-restroom', x: 0.1, y: 0.3, floorId: 3, type: 'restroom' as const, searchable: true, label: 'Restroom' },
    { id: 'sci-f1-stairs', x: 0.9, y: 0.5, floorId: 3, type: 'stairs' as const, searchable: false, label: 'Stairs' },
  ];
  return {
    buildings: [
      { id: 1, name: 'Library', floors: [
        { id: 1, floorNumber: 1, imagePath: '/lib-f1.png', updatedAt: '2024-01-01T00:00:00Z', nodes: libF1Nodes, edges: [{ id: 'e1', sourceId: 'lib-f1-entrance', targetId: 'lib-f1-reception', standardWeight: 0.1, accessibleWeight: 0.1, accessible: true, bidirectional: true }] },
        { id: 2, floorNumber: 2, imagePath: '/lib-f2.png', updatedAt: '2024-01-01T00:00:00Z', nodes: libF2Nodes, edges: [{ id: 'e2', sourceId: 'lib-f2-stairs', targetId: 'lib-f2-cafeteria', standardWeight: 0.3, accessibleWeight: 0.3, accessible: true, bidirectional: true }] },
      ]},
      { id: 2, name: 'Science Building', floors: [
        { id: 3, floorNumber: 1, imagePath: '/sci-f1.png', updatedAt: '2024-01-01T00:00:00Z', nodes: sciF1Nodes, edges: [{ id: 'e3', sourceId: 'sci-f1-entrance', targetId: 'sci-f1-lab-101', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true }] },
      ]},
    ],
  };
}

function makeGraph() {
  const result = normalizeNavGraph(createTestNavGraph());
  if (!result.ok) throw new Error('Failed to normalize: ' + result.error.message);
  return result.data;
}

describe('useLocationSearch', () => {
  describe('empty query', () => {
    it('returns all searchable nodes grouped by building/floor', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      expect(result.current.buildings).toHaveLength(2);
      expect(result.current.buildings[0]?.buildingName).toBe('Library');
    });

    it('excludes non-searchable nodes (stairs)', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      const allNodeIds = result.current.buildings.flatMap(b => b.floors.flatMap(f => f.nodes.map(n => n.node.id)));
      expect(allNodeIds).not.toContain('lib-f1-stairs');
      expect(allNodeIds).not.toContain('sci-f1-stairs');
    });

    it('totalMatches counts searchable nodes only', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      // Library F1: entrance, reception, study-a, elevator = 4; F2: cafeteria = 1; Science F1: entrance, lab-101, restroom = 3
      expect(result.current.totalMatches).toBe(8);
    });

    it('buildings sorted alphabetically', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      expect(result.current.buildings.map(b => b.buildingName)).toEqual(['Library', 'Science Building']);
    });

    it('floors sorted by floor number', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      const libFloors = result.current.buildings.find(b => b.buildingName === 'Library')?.floors.map(f => f.floorNumber);
      expect(libFloors).toEqual([1, 2]);
    });

    it('nodes sorted by label', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      const libF1Labels = result.current.buildings.find(b => b.buildingName === 'Library')?.floors.find(f => f.floorNumber === 1)?.nodes.map(n => n.node.label);
      expect(libF1Labels).toEqual(['Elevator', 'Main Entrance', 'Reception', 'Study Room A']);
    });
  });

  describe('prefix matching', () => {
    it('matches label prefix "Study"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Study'));
      expect(result.current.totalMatches).toBe(1);
    });

    it('case-insensitive matching', () => {
      const graph = makeGraph();
      const { result: lower } = renderHook(() => useLocationSearch(graph, 'study'));
      const { result: upper } = renderHook(() => useLocationSearch(graph, 'STUDY'));
      expect(lower.current.totalMatches).toBe(upper.current.totalMatches);
    });

    it('matches room number prefix "10"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, '10'));
      expect(result.current.totalMatches).toBe(2); // 101 Reception + 101 Chemistry Lab
    });

    it('matches description "chemistry"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'chemistry'));
      expect(result.current.totalMatches).toBe(1);
    });

    it('matches building name prefix "Sci"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Sci'));
      expect(result.current.buildings).toHaveLength(1);
      expect(result.current.buildings[0]?.buildingName).toBe('Science Building');
    });

    it('matches building name prefix "Lib"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Lib'));
      expect(result.current.buildings).toHaveLength(1);
      expect(result.current.buildings[0]?.buildingName).toBe('Library');
    });
  });

  describe('type filter', () => {
    it('excludes non-room nodes when typeFilter is {room}', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, '', new Set(['room'])));
      const allTypes = result.current.buildings.flatMap(b => b.floors.flatMap(f => f.nodes.map(n => n.node.type)));
      expect(allTypes.every(t => t === 'room')).toBe(true);
      expect(allTypes).toHaveLength(3);
    });

    it('filters to restroom only', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, '', new Set(['restroom'])));
      expect(result.current.totalMatches).toBe(1);
    });
  });

  describe('nonsense query', () => {
    it('returns empty result', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'xyz123'));
      expect(result.current.buildings).toHaveLength(0);
      expect(result.current.totalMatches).toBe(0);
    });
  });

  describe('result structure', () => {
    it('SearchNode includes full NavNode plus context', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Reception'));
      const sn = result.current.buildings[0].floors[0].nodes[0];
      expect(sn.node.id).toBe('lib-f1-reception');
      expect(sn.buildingId).toBe(1);
      expect(sn.buildingName).toBe('Library');
      expect(sn.floorId).toBe(1);
      expect(sn.floorNumber).toBe(1);
    });
  });
});

/**
 * Tests for mobile/hooks/useRouteSelection.ts
 *
 * Covers:
 * - setFromTap advances activeField
 * - swap exchanges start/destination
 * - clearAll resets state
 * - tapping same field skips duplicate (swap behavior)
 */

import { describe, expect, it } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useRouteSelection } from './useRouteSelection';
import { NavNode } from '../../src/shared/types';

function makeNode(id: string, label = `Node ${id}`): NavNode {
  return {
    id,
    x: 0.5,
    y: 0.5,
    floorId: 1,
    type: 'room',
    searchable: true,
    label,
    roomNumber: id,
  };
}

describe('useRouteSelection', () => {
  describe('initial state', () => {
    it('starts with null start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
    });

    it('starts with activeField = "start"', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.activeField).toBe('start');
    });

    it('starts with bothSelected = false', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.bothSelected).toBe(false);
    });
  });

  describe('setStart', () => {
    it('sets start node and advances activeField to "destination"', () => {
      const { result } = renderHook(() => useRouteSelection());
      const node = makeNode('node-a');

      act(() => {
        result.current.setStart(node);
      });

      expect(result.current.start).toEqual(node);
      expect(result.current.activeField).toBe('destination');
    });
  });

  describe('setDestination', () => {
    it('sets destination node and advances activeField to "start"', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(makeNode('dest-a'));
      });

      expect(result.current.destination).toBeDefined();
      expect(result.current.activeField).toBe('start');
    });
  });

  describe('setFromTap', () => {
    it('when activeField is "start", assigns to start and advances to "destination"', () => {
      const { result } = renderHook(() => useRouteSelection());
      const node = makeNode('tap-a');

      act(() => {
        result.current.setFromTap(node);
      });

      expect(result.current.start).toEqual(node);
      expect(result.current.activeField).toBe('destination');
    });

    it('when activeField is "destination", assigns to destination and advances to "start"', () => {
      const { result } = renderHook(() => useRouteSelection());

      // Advance to destination field
      act(() => {
        result.current.setActiveField('destination');
      });

      const node = makeNode('tap-b');
      act(() => {
        result.current.setFromTap(node);
      });

      expect(result.current.destination).toEqual(node);
      expect(result.current.activeField).toBe('start');
    });

    it('tapping the other field swaps start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      // Set start first
      act(() => {
        result.current.setStart(makeNode('start-x'));
      });

      // Now tap what is currently the start (node-x) while activeField is "destination"
      // This should trigger the swap
      act(() => {
        result.current.setActiveField('destination');
      });

      act(() => {
        result.current.setFromTap(makeNode('start-x'));
      });

      // The tapped node becomes destination, start-x becomes start
      // After swap: start = tapped node (start-x), dest = previous start (start-x)
      // Actually: when activeField=dest and start.id === tapped.id, swap happens
      // So: setStartState(prevDest=null) → start=start-x (same), setDestinationState(prevStart=start-x) → dest=start-x
      // Result: start=start-x, dest=start-x, activeField='start'
      expect(result.current.start?.id).toBe('start-x');
      expect(result.current.destination?.id).toBe('start-x');
    });

    it('tapping the same field that is already set skips duplicate and advances', () => {
      const { result } = renderHook(() => useRouteSelection());

      // Set start
      act(() => {
        result.current.setStart(makeNode('start-y'));
      });

      // activeField is now "destination"
      // Now tap what is currently the destination (null) — no swap, just set
      const node = makeNode('new-dest');
      act(() => {
        result.current.setFromTap(node);
      });

      expect(result.current.start?.id).toBe('start-y');
      expect(result.current.destination?.id).toBe('new-dest');
      expect(result.current.activeField).toBe('start');
    });
  });

  describe('swap', () => {
    it('exchanges start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('old-start'));
        result.current.setDestination(makeNode('old-dest'));
      });

      act(() => {
        result.current.swap();
      });

      expect(result.current.start?.id).toBe('old-dest');
      expect(result.current.destination?.id).toBe('old-start');
    });

    it('is a no-op when both are null', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.swap();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
    });

    it('is a no-op when only one is set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('only-start'));
      });

      act(() => {
        result.current.swap();
      });

      // With one null, the swap still exchanges null with the set value
      expect(result.current.start?.id ?? null).toBeNull();
      expect(result.current.destination?.id).toBe('only-start');
    });
  });

  describe('clearAll', () => {
    it('resets start, destination, and activeField', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
        result.current.setDestination(makeNode('d'));
        result.current.setActiveField('destination');
      });

      act(() => {
        result.current.clearAll();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
      expect(result.current.activeField).toBe('start');
      expect(result.current.bothSelected).toBe(false);
    });
  });

  describe('clearStart', () => {
    it('clears start and resets activeField to "start"', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
        result.current.setActiveField('destination');
      });

      act(() => {
        result.current.clearStart();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.activeField).toBe('start');
    });
  });

  describe('clearDestination', () => {
    it('clears destination and resets activeField to "destination"', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(makeNode('d'));
      });

      act(() => {
        result.current.clearDestination();
      });

      expect(result.current.destination).toBeNull();
      expect(result.current.activeField).toBe('destination');
    });
  });

  describe('bothSelected', () => {
    it('is true when both start and destination are set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
        result.current.setDestination(makeNode('d'));
      });

      expect(result.current.bothSelected).toBe(true);
    });

    it('is false when only start is set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
      });

      expect(result.current.bothSelected).toBe(false);
    });

    it('is false when only destination is set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(makeNode('d'));
      });

      expect(result.current.bothSelected).toBe(false);
    });
  });
});

/**
 * Tests for useRouteSession hook.
 *
 * Covers:
 * - idle state when no selection
 * - computing→ready on valid route
 * - no-route when unreachable
 * - error state for invalid nodes
 * - accessible mode filtering
 */

import { describe, expect, it, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { NavGraph } from '../../src/shared/types';
import { useRouteSession } from './useRouteSession';
import { normalizeNavGraph, NormalizedNavGraph } from '../domain/navGraph';

/** Extract normalized graph from result, throwing if normalization fails (test helper). */
function getTestGraph(navGraph: NavGraph): NormalizedNavGraph {
  const result = normalizeNavGraph(navGraph);
  if (!result.ok) {
    throw new Error(`Test graph normalization failed: ${result.error.code}`);
  }
  return result.data;
}

/** Build a minimal two-room graph on a single floor with one connecting edge. */
function createTestNavGraph(): NavGraph {
  return {
    buildings: [
      {
        id: 1,
        name: 'Test Building',
        floors: [
          {
            id: 1,
            floorNumber: 1,
            imagePath: '',
            updatedAt: '2024-01-01T00:00:00Z',
            nodes: [
              {
                id: 'room-a',
                x: 0.1,
                y: 0.5,
                floorId: 1,
                type: 'room',
                searchable: true,
                label: 'Room A',
                roomNumber: 'A101',
              },
              {
                id: 'room-b',
                x: 0.9,
                y: 0.5,
                floorId: 1,
                type: 'room',
                searchable: true,
                label: 'Room B',
                roomNumber: 'B101',
              },
            ],
            edges: [
              {
                id: 'edge-a-b',
                sourceId: 'room-a',
                targetId: 'room-b',
                standardWeight: 0.8,
                accessibleWeight: 0.8,
                accessible: true,
                bidirectional: true,
              },
            ],
          },
        ],
      },
    ],
  };
}

/** Build a graph with a disconnected component (no route between room-a and room-c). */
function createDisconnectedNavGraph(): NavGraph {
  return {
    buildings: [
      {
        id: 1,
        name: 'Test Building',
        floors: [
          {
            id: 1,
            floorNumber: 1,
            imagePath: '',
            updatedAt: '2024-01-01T00:00:00Z',
            nodes: [
              { id: 'room-a', x: 0.1, y: 0.5, floorId: 1, type: 'room', searchable: true, label: 'Room A', roomNumber: 'A101' },
              { id: 'room-b', x: 0.9, y: 0.5, floorId: 1, type: 'room', searchable: true, label: 'Room B', roomNumber: 'B101' },
            ],
            edges: [
              { id: 'edge-a-b', sourceId: 'room-a', targetId: 'room-b', standardWeight: 0.8, accessibleWeight: 0.8, accessible: true, bidirectional: true },
            ],
          },
          {
            id: 2,
            floorNumber: 2,
            imagePath: '',
            updatedAt: '2024-01-01T00:00:00Z',
            nodes: [
              { id: 'room-c', x: 0.5, y: 0.5, floorId: 2, type: 'room', searchable: true, label: 'Room C', roomNumber: 'C101' },
            ],
            edges: [],
          },
        ],
      },
    ],
  };
}

/** Build a graph with a stairs-only inter-floor connection (blocked in accessible mode). */
function createStairsOnlyNavGraph(): NavGraph {
  return {
    buildings: [
      {
        id: 1,
        name: 'Test Building',
        floors: [
          {
            id: 1,
            floorNumber: 1,
            imagePath: '',
            updatedAt: '2024-01-01T00:00:00Z',
            nodes: [
              { id: 'room-f1', x: 0.1, y: 0.5, floorId: 1, type: 'room', searchable: true, label: 'Room F1', roomNumber: 'F101' },
              {
                id: 'stairs-1',
                x: 0.9,
                y: 0.5,
                floorId: 1,
                type: 'stairs',
                searchable: false,
                label: 'Stairs',
                connectsToNodeAboveId: 'stairs-2',
                connectsToFloorAboveId: 2,
                connectsToNodeBelowId: undefined,
                connectsToFloorBelowId: undefined,
              },
            ],
            edges: [
              { id: 'edge-f1-stairs', sourceId: 'room-f1', targetId: 'stairs-1', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
            ],
          },
          {
            id: 2,
            floorNumber: 2,
            imagePath: '',
            updatedAt: '2024-01-01T00:00:00Z',
            nodes: [
              { id: 'room-f2', x: 0.9, y: 0.5, floorId: 2, type: 'room', searchable: true, label: 'Room F2', roomNumber: 'F201' },
              {
                id: 'stairs-2',
                x: 0.9,
                y: 0.5,
                floorId: 2,
                type: 'stairs',
                searchable: false,
                label: 'Stairs',
                connectsToNodeBelowId: 'stairs-1',
                connectsToFloorBelowId: 1,
                connectsToNodeAboveId: undefined,
                connectsToFloorAboveId: undefined,
              },
            ],
            edges: [
              { id: 'edge-f2-stairs', sourceId: 'room-f2', targetId: 'stairs-2', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
            ],
          },
        ],
      },
    ],
  };
}

function makeNavNode(id: string, label: string): import('../../src/shared/types').NavNode {
  return {
    id,
    x: 0.5,
    y: 0.5,
    floorId: 1,
    type: 'room',
    searchable: true,
    label,
  };
}

// ============================================================
// Tests
// ============================================================

describe('useRouteSession', () => {
  describe('idle state', () => {
    it('returns idle phase when no start is set', () => {
      const graph = getTestGraph(createTestNavGraph());
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: null, destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      expect(result.current.sessionState.phase).toBe('idle');
    });

    it('returns idle phase when no destination is set', () => {
      const graph = getTestGraph(createTestNavGraph());
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: null },
        }),
      );

      expect(result.current.sessionState.phase).toBe('idle');
    });

    it('returns idle phase when both are null', () => {
      const graph = getTestGraph(createTestNavGraph());
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: null, destination: null },
        }),
      );

      expect(result.current.sessionState.phase).toBe('idle');
    });
  });

  describe('ready state', () => {
    it('returns ready phase when both start and destination are valid and reachable', () => {
      const graph = getTestGraph(createTestNavGraph());
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      expect(result.current.sessionState.phase).toBe('ready');
      const state = result.current.sessionState;
      if (state.phase !== 'ready') throw new Error('Expected ready state');
      expect(state.path.found).toBe(true);
      expect(state.directions.steps.length).toBeGreaterThan(0);
    });

    it('path result contains correct node IDs', () => {
      const graph = getTestGraph(createTestNavGraph());
      const { result } = renderHook(() =>
        useRouteSession({
          graph,
          selection: { start: makeNavNode('room-a', 'Room A'), destination: makeNavNode('room-b', 'Room B') },
        }),
      );

      const state = result.current.sessionState;
      if (state.phase !== 'ready') throw new Error('Expected ready state');
      expect(state.path.nodeIds).toContain('room-a');
      expect(state.path.nodeIds).toContain('room-b');
    });

    it('directions result contains arrive step', () => {
